public class AutofillDetector extends Detector implements Detector.XmlScanner {

    public static final Issue ISSUE = Issue.create(
            "Autofill",
            "Use Autofill",
            "Specify an `autofillHints` attribute when targeting SDK version 26 or higher or explicitly specify that the view is not important for autofill. ...",
            Category.USABILITY,
            5,
            Severity.WARNING,
            new Implementation(
                    AutofillDetector.class,
                    Scope.RESOURCE_FILE_SCOPE));

    private static final Set<String> AUTOFILLABLE_TAGS = new HashSet<>(Arrays.asList(
            SdkConstants.AUTO_COMPLETE_TEXT_VIEW,
            SdkConstants.MULTI_AUTO_COMPLETE_TEXT_VIEW,
            SdkConstants.SEARCH_VIEW,
            SdkConstants.EXTRACT_EDIT_TEXT,
            "SearchAutoComplete"
    ));

    @Override
    public boolean appliesTo(ResourceFolderType folderType) {
        return folderType == ResourceFolderType.LAYOUT;
    }

    @Override
    public Collection<String> getApplicableElements() {
        return ALL;
    }

    @Override
    public void visitElement(XmlContext context, Element element) {
        if (context.getMainProject().getTargetSdk() < 26) {
            return;
        }

        if (!isAutofillable(context, element)) {
            return;
        }

        if (element.hasAttributeNS(SdkConstants.ANDROID_URI, SdkConstants.ATTR_AUTOFILL_HINTS)) {
            return;
        }

        if (!isImportantForAutofill(element)) {
            return;
        }

        context.report(ISSUE, element, context.getLocation(element),
                "Missing `autofillHints` attribute: either specify it or set `importantForAutofill` to \"no\" on this view or a parent view.");
    }

    private static boolean isAutofillable(XmlContext context, Element element) {
        String tag = element.getLocalName();
        if (tag == null) {
            return false;
        }
        int dot = tag.lastIndexOf('.');
        String simpleName = dot == -1 ? tag : tag.substring(dot + 1);
        if (simpleName.endsWith("EditText")) {
            return true;
        }
        if (AUTOFILLABLE_TAGS.contains(simpleName)) {
            return true;
        }
        return element.hasAttributeNS(SdkConstants.ANDROID_URI, SdkConstants.ATTR_INPUT_TYPE);
    }

    private static boolean isImportantForAutofill(Element element) {
        String value = element.getAttributeNS(SdkConstants.ANDROID_URI,
                SdkConstants.ATTR_IMPORTANT_FOR_AUTOFILL);
        if (!value.isEmpty()) {
            if (value.equals(SdkConstants.VALUE_NO)
                    || value.equals(SdkConstants.VALUE_NO_EXCLUDE_DESCENDANTS)) {
                return false;
            }
            // yes or yesExcludeDescendants: important
            return true;
        }

        Node parent = element.getParentNode();
        while (parent instanceof Element) {
            Element parentElement = (Element) parent;
            String parentValue = parentElement.getAttributeNS(SdkConstants.ANDROID_URI,
                    SdkConstants.ATTR_IMPORTANT_FOR_AUTOFILL);
            if (!parentValue.isEmpty()) {
                if (parentValue.equals(SdkConstants.VALUE_NO_EXCLUDE_DESCENDANTS)
                        || parentValue.equals(SdkConstants.VALUE_YES_EXCLUDE_DESCENDANTS)) {
                    return false;
                }
            }
            parent = parent.getParentNode();
        }
        return true;
    }
}
